#define TUR_TEST_REGISTRY_MAX 1024
#define BACKTRACK_DEPTH_DEFAULT 0
typedef int64_t (*tur_test_callback_t)(void);
static const char *tur_test_registry_names[TUR_TEST_REGISTRY_MAX];
static tur_test_callback_t tur_test_registry_fns[TUR_TEST_REGISTRY_MAX];
static int64_t tur_test_registry_count = 0;

int64_t tur_test_register(const char *name, void *test_fn) {
    if (!test_fn) return 0;
    if (tur_test_registry_count >= TUR_TEST_REGISTRY_MAX) return 0;
    tur_test_registry_names[tur_test_registry_count] = name ? name : "<unnamed>";
    tur_test_registry_fns[tur_test_registry_count] = (tur_test_callback_t)test_fn;
    tur_test_registry_count++;
    return 1;
}

int64_t tur_test_run_all(void) {
    int64_t passed = 0;
    int64_t failed = 0;
    for (int64_t i = 0; i < tur_test_registry_count; i++) {
        tur_test_callback_t fn = tur_test_registry_fns[i];
        int64_t rc = fn ? fn() : 0;
        if (rc == 1) {
            putchar('.');
            putchar('\n');
            passed++;
        } else {
            putchar('F');
            putchar('\n');
            printf("%s\n", tur_test_registry_names[i]);
            failed++;
        }
    }
    printf("summary: %lld passed, %lld failed\n",
           (long long)passed, (long long)failed);
    return failed == 0 ? 0 : 1;
}

/* tur_frame - phase 4 v1 lowering (from runtime.h) */
typedef void (*defer_fn_t)(void *env);
#define TUR_FRAME_MAX_DEFERS 32

typedef struct tur_frame {
    defer_fn_t defers[TUR_FRAME_MAX_DEFERS];
    void *envs[TUR_FRAME_MAX_DEFERS];
    int n;
    struct tur_frame *parent;
    bool may_capture;
} tur_frame;

static inline void tur_frame_init(tur_frame *f, tur_frame *parent) {
    f->n = 0; f->parent = parent; f->may_capture = false;
}
static inline int tur_frame_push_defer(tur_frame *f, defer_fn_t thunk, void *env) {
    if (f->n >= TUR_FRAME_MAX_DEFERS) return -1;
    f->defers[f->n] = thunk;
    f->envs[f->n] = env;
    f->n++;
    return 0;
}
static void tur_frame_fire_lifo(tur_frame *f) {
    for (int i = f->n - 1; i >= 0; i--) f->defers[i](f->envs[i]);
    f->n = 0;
}
static void tur_frame_fire_chain(tur_frame *f) {
    tur_frame *frames[64];
    int n_frames = 0;
    for (tur_frame *cur = f; cur != NULL && n_frames < 64; cur = cur->parent) {
        frames[n_frames++] = cur;
    }
    for (int i = n_frames - 1; i >= 0; i--) {
        tur_frame_fire_lifo(frames[i]);
    }
}

/* Phase R2/R6: tur_panic */
static int tur_panic_in_progress = 0;
static tur_frame *global_panic_frame = NULL;
static int g_panic_trace = 0;  /* Set by compiler when --panic-trace is used */
static int64_t g_tur_args = 0;  /* *args*: CLI arguments as list of :cstr (set in main) */
static void tur_panic_set_frame(tur_frame *f) {
    global_panic_frame = f;
}
static void tur_panic_print_scope_chain(void) {
    if (!g_panic_trace || !global_panic_frame) return;
    fprintf(stderr, "  scope chain:\n");
    tur_frame *frames[64];
    int n_frames = 0;
    for (tur_frame *cur = global_panic_frame; cur != NULL && n_frames < 64; cur = cur->parent) {
        frames[n_frames++] = cur;
    }
    for (int i = 0; i < n_frames; i++) {
        fprintf(stderr, "    at frame %p (parent: %p, n_defers: %d)\n",
                (void*)frames[i], (void*)frames[i]->parent, frames[i]->n);
    }
}

typedef struct tur_panic_payload tur_panic_payload;
typedef struct tur_handler_node { jmp_buf buf; struct tur_handler_node *parent; } tur_handler_node;
static __thread tur_handler_node *tur_handler_chain = NULL;
static __thread int tur_panicking = 0;
#define TUR_SC_MAXP 8
#define TUR_SC_MAXN 32
typedef struct tur_cont { int tag; tur_handler_node *boundary; struct tur_cont *next; int64_t saved[TUR_SC_MAXN]; uint32_t aggr_mask; } tur_cont;
static inline int64_t tur_sc_bits_f64(double d){ int64_t i; memcpy(&i,&d,sizeof i); return i; }
static inline double  tur_sc_f64_from_bits(int64_t i){ double d; memcpy(&d,&i,sizeof d); return d; }
static inline int64_t tur_sc_bits_f32(float f){ int64_t i=0; memcpy(&i,&f,sizeof f); return i; }
static inline float   tur_sc_f32_from_bits(int64_t i){ float f; memcpy(&f,&i,sizeof f); return f; }
static tur_panic_payload *global_panic_payload;
static tur_panic_payload *panic_payload_new(int, void *, const char *, int);
static void tur_panic(const char *msg) {
    if (tur_panic_in_progress) {
        fprintf(stderr, "double panic: aborting\n");
        abort();
    }
    tur_panic_in_progress = 1;
    if (tur_handler_chain) {
        global_panic_payload = panic_payload_new(5, msg ? strdup(msg) : NULL, __FILE__, __LINE__);
        if (global_panic_frame) { tur_frame_fire_chain(global_panic_frame); }
        tur_panicking = 1;
        return;
    }
    fprintf(stderr, "panic at %s:%d: %s\n", __FILE__, __LINE__, msg ? msg : "(no message)");
    tur_panic_print_scope_chain();
    if (global_panic_frame) {
        tur_frame_fire_chain(global_panic_frame);
    }
    fflush(NULL);
    abort();
}

/* Phase R5: tur_panic_abort - no unwinding, immediate abort */
static void tur_panic_abort(const char *msg) {
    fprintf(stderr, "panic (no unwind): %s\n", msg ? msg : "(no message)");
    abort();
}

static void tur_panic_with(int type_tag, void *payload, const char *file, int line);

/* Phase R2: tur_panic_with types */
struct tur_panic_payload {
    int type_tag;
    void *value;
    const char *file;
    int line;
};

static tur_panic_payload *global_panic_payload = NULL;

static tur_panic_payload *panic_payload_new(int type_tag, void *payload, const char *file, int line) {
    tur_panic_payload *p = (tur_panic_payload *)malloc(sizeof(tur_panic_payload));
    if (!p) { fprintf(stderr, "panic: oom\n"); abort(); }
    p->type_tag = type_tag; p->value = payload; p->file = file; p->line = line;
    return p;
}

static void panic_payload_free(tur_panic_payload *p) {
    if (p) { free(p); }
}

static int tur_panic_payload_type(tur_panic_payload *p) {
    return p ? p->type_tag : 0;
}

static void *tur_panic_payload_value(tur_panic_payload *p) {
    return p ? p->value : NULL;
}

static const char *tur_panic_payload_file(tur_panic_payload *p) {
    return p ? p->file : NULL;
}

static int tur_panic_payload_line(tur_panic_payload *p) {
    return p ? p->line : 0;
}

static void *tur_panic_payload_downcast(tur_panic_payload *p, int target_type) {
    if (!p || p->type_tag != target_type) return NULL;
    return p->value;
}

/* Phase R2: catch-unwind/catch-panic-of */
typedef enum { TUR_RESULT_OK, TUR_RESULT_ERR } tur_result_tag;
typedef struct tur_result tur_result;
struct tur_result {
    tur_result_tag tag;
    union { int64_t ok_val; void *ok_ptr; tur_panic_payload *err; } u;
};

typedef void (*tur_thunk_fn)(void *env, tur_result *out);

static bool tur_catch_unwind(tur_thunk_fn thunk, void *env, tur_result *out) {
    tur_handler_node __node; __node.parent = tur_handler_chain; tur_handler_chain = &__node;
    if (setjmp(__node.buf) == 0) {
        thunk(env, out);
        tur_handler_chain = __node.parent;
        if (global_panic_payload) {
            panic_payload_free(global_panic_payload);
            global_panic_payload = NULL;
        }
        return false;
    } else {
        tur_handler_chain = __node.parent;
        tur_panic_in_progress = 0;
        out->tag = TUR_RESULT_ERR;
        out->u.err = global_panic_payload;
        global_panic_payload = NULL;
        return true;
    }
}

static bool tur_catch_panic_of(int expected_type, tur_thunk_fn thunk, void *env, tur_result *out) {
    tur_handler_node __node; __node.parent = tur_handler_chain; tur_handler_chain = &__node;
    if (setjmp(__node.buf) == 0) {
        thunk(env, out);
        tur_handler_chain = __node.parent;
        if (global_panic_payload) {
            panic_payload_free(global_panic_payload);
            global_panic_payload = NULL;
        }
        return false;
    } else {
        tur_handler_chain = __node.parent;
        tur_panic_in_progress = 0;
        if (global_panic_payload && global_panic_payload->type_tag == expected_type) {
            out->tag = TUR_RESULT_ERR;
            out->u.err = global_panic_payload;
            global_panic_payload = NULL;
            return true;
        } else {
        if (global_panic_payload) {
            /* Type mismatch - re-panic to the next outer boundary (restored above) */
            tur_panic_with(global_panic_payload->type_tag, global_panic_payload->value,
                           global_panic_payload->file, global_panic_payload->line);
        }
        return false;
        }
    }
}

/* Phase R2: catch-unwind special-form helpers (result-box ABI) */
static int64_t tur_catch_unwind_box(int64_t thunk) {
    tur_handler_node *__node = (tur_handler_node *)malloc(sizeof(tur_handler_node));
    __node->parent = tur_handler_chain; tur_handler_chain = __node;
    int64_t __v = TUR_APPLY0(thunk);
    tur_handler_chain = __node->parent; free(__node);
    if (tur_panicking) {
        tur_panicking = 0; tur_panic_in_progress = 0;
        tur_panic_payload *__p = global_panic_payload;
        global_panic_payload = NULL;
        return tur_box_err((int64_t)(intptr_t)__p);
    }
    return tur_box_ok(__v);
}

static int64_t tur_catch_panic_of_box(int expected_type, int64_t thunk) {
    tur_handler_node *__node = (tur_handler_node *)malloc(sizeof(tur_handler_node));
    __node->parent = tur_handler_chain; tur_handler_chain = __node;
    int64_t __v = TUR_APPLY0(thunk);
    tur_handler_chain = __node->parent; free(__node);
    if (tur_panicking) {
        tur_panic_payload *__p = global_panic_payload;
        if (__p && __p->type_tag == expected_type) {
            tur_panicking = 0; tur_panic_in_progress = 0;
            global_panic_payload = NULL;
            return tur_box_err((int64_t)(intptr_t)__p);
        }
        /* type mismatch: leave the signal + payload staged so it
         * propagates to the next outer boundary via the return path. */
        return tur_box_err(0);
    }
    return tur_box_ok(__v);
}

static void tur_result_box_free(int64_t __r) __attribute__((unused));
static void tur_result_box_free(int64_t __r) {
    tur_result_box_t *__b = (tur_result_box_t *)(intptr_t)__r;
    if (!__b) return;
    if (!__b->is_ok) free((tur_panic_payload *)(intptr_t)__b->err_val);
    free(__b);
}

static void tur_result_box_free_shallow(int64_t __r) __attribute__((unused));
static void tur_result_box_free_shallow(int64_t __r) {
    free((tur_result_box_t *)(intptr_t)__r);
}

/* CPS substrate (cps-transform-plan): multi-prompt delimited-control machine.
 * Heap-reified continuation chains (DK); a reset is a prompt, a shift slices
 * the chain up to the nearest prompt. Faithful port of src/runtime/cps_prompt.c.
 * Capture is O(depth-of-slice) and unbounded -- no 16-frame ceiling. */
#define DK_ROOT_TAG 0
typedef struct DK DK;
typedef intptr_t (*DKFrame)(intptr_t env, intptr_t value);
typedef intptr_t (*DKBody)(intptr_t env, DK *subk);
typedef intptr_t (*DKHandler)(intptr_t env, intptr_t arg, DK *subk);
typedef intptr_t (*DKResumeFrame)(intptr_t env, intptr_t value, DK *rest);
typedef enum { DKK_DONE, DKK_FRAME, DKK_PROMPT, DKK_SHIFT, DKK_SHIFT0, DKK_HANDLER, DKK_RESUME_FRAME } DKKind;
struct DK {
    DKKind kind; DKFrame fn; intptr_t env; int tag;
    DKBody body; intptr_t body_env;
    DKHandler handler; intptr_t handler_env; bool shallow;
    DKResumeFrame rfn; DK *next;
};
static DK *dk_new(DKKind kind, DK *next) {
    DK *k = (DK *)calloc(1, sizeof(DK)); k->kind = kind; k->next = next; return k;
}
static DK *dk_done(void) { return dk_new(DKK_DONE, NULL); }
static DK *dk_frame(DKFrame fn, intptr_t env, DK *next) {
    DK *k = dk_new(DKK_FRAME, next); k->fn = fn; k->env = env; return k;
}
static DK *dk_frame_resume(DKResumeFrame fn, intptr_t env, DK *next) {
    DK *k = dk_new(DKK_RESUME_FRAME, next); k->rfn = fn; k->env = env; return k;
}
static DK *dk_prompt(int tag, DK *next) {
    DK *k = dk_new(DKK_PROMPT, next); k->tag = tag; return k;
}
static DK *dk_shift_impl(DKKind kind, int tag, DKBody body, intptr_t env, DK *next) {
    DK *k = dk_new(kind, next); k->tag = tag; k->body = body; k->body_env = env; return k;
}
static DK *dk_shift(int tag, DKBody body, intptr_t env, DK *next) {
    return dk_shift_impl(DKK_SHIFT, tag, body, env, next);
}
static DK *dk_shift0(int tag, DKBody body, intptr_t env, DK *next) {
    return dk_shift_impl(DKK_SHIFT0, tag, body, env, next);
}
static DK *dk_handler_impl(int tag, DKHandler fn, intptr_t env, bool shallow, DK *next) {
    DK *k = dk_new(DKK_HANDLER, next); k->tag = tag; k->handler = fn; k->handler_env = env; k->shallow = shallow; return k;
}
static DK *dk_handler(int tag, DKHandler fn, intptr_t env, DK *next) {
    return dk_handler_impl(tag, fn, env, false, next);
}
static DK *dk_handler_shallow(int tag, DKHandler fn, intptr_t env, DK *next) {
    return dk_handler_impl(tag, fn, env, true, next);
}
static DK *dk_copy_node(const DK *n);
static DK *dk_copy_node(const DK *n) {
    DK *c = dk_new(n->kind, NULL); c->fn = n->fn; c->env = n->env; c->tag = n->tag;
    c->body = n->body; c->body_env = n->body_env;
    c->handler = n->handler; c->handler_env = n->handler_env; c->shallow = n->shallow;
    c->rfn = n->rfn; return c;
}
static DK *dk_copy_enclosing_handlers(const DK *from) {
    DK *head = NULL, *tail = NULL;
    for (const DK *p = from; p && p->kind != DKK_DONE; p = p->next) {
        if (p->kind != DKK_HANDLER) continue;
        DK *c = dk_copy_node(p);
        if (!head) head = tail = c; else { tail->next = c; tail = c; }
    }
    DK *done = dk_done();
    if (!head) return done;
    tail->next = done; return head;
}
static DK *dk_copy_range(const DK *from, const DK *stop) {
    DK *head = NULL, *tail = NULL;
    for (const DK *p = from; p && p != stop; p = p->next) {
        DK *c = dk_copy_node(p);
        if (!head) head = tail = c; else { tail->next = c; tail = c; }
    }
    return head;
}
static DK *dk_append(DK *a, DK *b) {
    if (!a) return b;
    DK *p = a;
    while (p->next) p = p->next;
    p->next = b;
    return a;
}
static void dk_free(DK *k) { while (k) { DK *n = k->next; free(k); k = n; } }
/* Free a single spliced node without following ->next -- used to reclaim the
 * one-off shift/perform node whose ->next points into an enclosing continuation
 * (dk_free would walk into that continuation and risk a double free).  See
 * docs/archive/cps-delimited-dk-node-leak.md. */
__attribute__((unused)) static void dk_free_node(DK *k) { free(k); }
/* Structural-chain reaping (docs/archive/cps-delimited-dk-node-leak.md).
 * reset/handle install a prompt/handler chain as the current continuation and
 * thread it through the delimited body in TAIL position, so the install site
 * never regains control to free it.  Each chain is self-contained (its tail is
 * dk_done; its frame envs carry the enclosing k as an intptr, not via ->next),
 * so once the outermost dk_run has fully settled every registered chain is dead
 * and dk_free-able without aliasing another.  We register each at construction
 * and reap at the outermost direct->cps entry boundary.  The same registry
 * reclaims per-continuation env structs (plain malloc, freed one-by-one). */
static void **__dk_reap_v = NULL;
static unsigned char *__dk_reap_kind = NULL;  /* 1 = DK chain (dk_free), 0 = plain (free) */
static size_t __dk_reap_n = 0, __dk_reap_cap = 0;
static int __dk_entry_depth = 0;
static void __dk_reap_push(void *p, unsigned char kind) {
    if (__dk_reap_n == __dk_reap_cap) {
        __dk_reap_cap = __dk_reap_cap ? __dk_reap_cap * 2 : 16;
        __dk_reap_v = (void **)realloc(__dk_reap_v, __dk_reap_cap * sizeof(void *));
        __dk_reap_kind = (unsigned char *)realloc(__dk_reap_kind, __dk_reap_cap);
    }
    __dk_reap_v[__dk_reap_n] = p; __dk_reap_kind[__dk_reap_n] = kind; __dk_reap_n++;
}
__attribute__((unused)) static DK *__dk_reap_keep(DK *k) { __dk_reap_push(k, 1); return k; }
__attribute__((unused)) static intptr_t __dk_reap_ptr(intptr_t p) { __dk_reap_push((void *)p, 0); return p; }
/* Register a single spliced node (->next points into an enclosing k) for a
 * single-node free at reap -- dk_free would walk into the enclosing chain. */
__attribute__((unused)) static DK *__dk_reap_node(DK *k) { __dk_reap_push(k, 0); return k; }
static void __dk_reap_run(void) {
    for (size_t i = 0; i < __dk_reap_n; i++) {
        if (__dk_reap_kind[i]) dk_free((DK *)__dk_reap_v[i]); else free(__dk_reap_v[i]);
    }
    free(__dk_reap_v); free(__dk_reap_kind);
    __dk_reap_v = NULL; __dk_reap_kind = NULL; __dk_reap_n = __dk_reap_cap = 0;
}
static intptr_t dk_run_impl(DK *k, intptr_t v, bool root) {
    while (k) {
        switch (k->kind) {
            case DKK_DONE: return v;
            case DKK_PROMPT: case DKK_HANDLER: k = k->next; break;
            case DKK_FRAME: v = k->fn(k->env, v); k = k->next; break;
            case DKK_RESUME_FRAME: return k->rfn(k->env, v, k->next);
            case DKK_SHIFT:
            case DKK_SHIFT0: {
                DK *P = k->next;
                while (P && !(P->kind == DKK_PROMPT && P->tag == k->tag)
                         && P->kind != DKK_DONE) P = P->next;
                bool to_root = (!P || P->kind == DKK_DONE);
                bool reinstall = (k->kind == DKK_SHIFT);
                DK *sub = dk_copy_range(k->next, P);
                DK *tail = reinstall
                    ? dk_prompt(to_root ? DK_ROOT_TAG : k->tag, dk_done()) : dk_done();
                sub = dk_append(sub, tail);
                intptr_t bodyval = k->body(k->body_env, sub);
                dk_free(sub);
                if (to_root) return bodyval;
                k = P->next; v = bodyval; break;
            }
        }
    }
    (void)root; return v;
}
static intptr_t dk_run(DK *k, intptr_t v)      { return dk_run_impl(k, v, false); }
static intptr_t dk_run_root(DK *k, intptr_t v) { return dk_run_impl(k, v, true); }
static intptr_t dk_invoke(DK *sub, intptr_t w) {
    DK *c = dk_copy_range(sub, NULL); intptr_t r = dk_run_impl(c, w, false);
    dk_free(c); return r;
}
static intptr_t dk_perform(int tag, intptr_t arg, DK *k) {
    DK *H = k;
    while (H && !(H->kind == DKK_HANDLER && H->tag == tag) && H->kind != DKK_DONE) H = H->next;
    if (!H || H->kind == DKK_DONE) { fprintf(stderr, "tur: unhandled effect (tag %d)\n", tag); abort(); }
    DK *sub = dk_copy_range(k, H);
    DK *tail = H->shallow ? dk_copy_enclosing_handlers(H->next)
                          : dk_handler(tag, H->handler, H->handler_env, dk_done());
    sub = dk_append(sub, tail);
    intptr_t r = H->handler(H->handler_env, arg, sub);
    dk_free(sub);
    return dk_run_impl(H->next, r, false);
}
/* Abortive shift body: deliver the precomputed receiver result f(v),
 * ignoring the captured sub-continuation (Turmeric shift never resumes it). */
static intptr_t __dk_abort_body(intptr_t env, DK *subk) { (void)subk; return env; }

/* Phase 19: Algebraic effect handler chain */
typedef struct { bool consumed; void *origin_fiber; } TurContK;

/* Phase 19D: Effect-capture continuation context */
typedef struct TurEffectCaptureCtx TurEffectCaptureCtx;
